# Mean-field kinetic model for a dilute suspension of Marangoni surfers on a doubly
# periodic domain. The distribution ψ(x, y, θ) is advected by self-propulsion U p(θ)
# and by the surface flow generated by the polarization ∫ p ψ dθ, rotated by the surface
# strain rate through the shape factor λ, and diffused with coefficients dT and dR.
# Discretized pseudo-spectrally in (x, y, θ) and integrated with variable-step SBDF2
# (explicit advection, implicit diffusion). Driven by main.jl.

using FFTW
using Printf
using Random

struct SpectralGrid
    Nx::Int
    Ny::Int
    Nθ::Int
    Lx::Float64
    Ly::Float64
    x::Vector{Float64}
    y::Vector{Float64}
    θ::Vector{Float64}
    kx::Vector{Float64}
    ky::Vector{Float64}
    kθ::Vector{Float64}
    dx::Float64
    dy::Float64
    dθ::Float64
    keep_x::Vector{Bool}
    keep_y::Vector{Bool}
    keep_θ::Vector{Bool}
end

function SpectralGrid(Nx::Int, Ny::Int, Nθ::Int; Lx=2π, Ly=2π)

    x = collect((0:Nx-1) .* (Lx / Nx))
    y = collect((0:Ny-1) .* (Ly / Ny))
    θ = collect((0:Nθ-1) .* (2π / Nθ))

    nx = collect(fftfreq(Nx, Nx))       # integer mode numbers, FFT order
    ny = collect(fftfreq(Ny, Ny))
    nθ = collect(fftfreq(Nθ, Nθ))

    kx = (2π / Lx) .* nx
    ky = (2π / Ly) .* ny

    # 2/3 rule: the quadratic fluxes are truncated above N/3
    keep_x = abs.(nx) .<= Nx ÷ 3
    keep_y = abs.(ny) .<= Ny ÷ 3
    keep_θ = abs.(nθ) .<= Nθ ÷ 3

    return SpectralGrid(Nx, Ny, Nθ, Lx, Ly, x, y, θ, kx, ky, nθ,
                         Lx/Nx, Ly/Ny, 2π/Nθ, keep_x, keep_y, keep_θ)
end

function moments(ψ, G::SpectralGrid)
    cθ = reshape(cos.(G.θ), 1, 1, :)
    sθ = reshape(sin.(G.θ), 1, 1, :)
    ρ  = G.dθ .* dropdims(sum(ψ,        dims=3), dims=3)
    m1 = G.dθ .* dropdims(sum(ψ .* cθ,  dims=3), dims=3)
    m2 = G.dθ .* dropdims(sum(ψ .* sθ,  dims=3), dims=3)
    return ρ, m1, m2
end

function velocity(ψ, G::SpectralGrid; β=π/2)

    _, m1, m2 = moments(ψ, G)
    m̂1, m̂2 = fft(m1), fft(m2)

    û1  = zeros(ComplexF64, G.Nx, G.Ny)
    û2  = zeros(ComplexF64, G.Nx, G.Ny)
    Ê11 = zeros(ComplexF64, G.Nx, G.Ny)
    Ê12 = zeros(ComplexF64, G.Nx, G.Ny)
    Ê22 = zeros(ComplexF64, G.Nx, G.Ny)

    @inbounds for j in 1:G.Ny, i in 1:G.Nx
        kx, ky = G.kx[i], G.ky[j]
        k2 = kx^2 + ky^2
        k2 == 0 && continue
        S = β * (kx * m̂1[i,j] + ky * m̂2[i,j]) / (2 * k2 * sqrt(k2))
        û1[i,j] = kx * S
        û2[i,j] = ky * S
        Ê11[i,j] = im * kx * û1[i,j]
        Ê12[i,j] = im * ky * û1[i,j]
        Ê22[i,j] = im * ky * û2[i,j]
    end

    return real.(ifft(û1)),  real.(ifft(û2)),
           real.(ifft(Ê11)), real.(ifft(Ê12)), real.(ifft(Ê22))

end

function rhs(ψ, G::SpectralGrid; U=0.098175, λ=0.0, β=π/2,
                       dT=0.0, dR=0.0, dealias=true)

    u1, u2, E11, E12, E22 = velocity(ψ, G; β=β)

    cθ  = reshape(cos.(G.θ),      1, 1, :)
    sθ  = reshape(sin.(G.θ),      1, 1, :)
    c2θ = reshape(cos.(2 .* G.θ), 1, 1, :)
    s2θ = reshape(sin.(2 .* G.θ), 1, 1, :)

    u1r = reshape(u1, G.Nx, G.Ny, 1)
    u2r = reshape(u2, G.Nx, G.Ny, 1)

    # conservative fluxes
    Fx = (U .* cθ .+ u1r) .* ψ
    Fy = (U .* sθ .+ u2r) .* ψ

    θdot = λ .* (0.5 .* reshape(E22 .- E11, G.Nx, G.Ny, 1) .* s2θ .+
                        reshape(E12,        G.Nx, G.Ny, 1) .* c2θ)
    Fθ = θdot .* ψ

    # spatial divergence (+ translational diffusion)
    F̂x, F̂y = fft(Fx, (1,2)), fft(Fy, (1,2))
    ψ̂xy = dT > 0 ? fft(ψ, (1,2)) : nothing
    A = similar(F̂x)
    @inbounds for m in 1:G.Nθ, j in 1:G.Ny, i in 1:G.Nx
        kx, ky = G.kx[i], G.ky[j]
        nl = -im * (kx * F̂x[i,j,m] + ky * F̂y[i,j,m])
        if dealias && !(G.keep_x[i] && G.keep_y[j])
            nl = 0.0 + 0.0im
        end
        A[i,j,m] = dT > 0 ? nl - dT * (kx^2 + ky^2) * ψ̂xy[i,j,m] : nl
    end
    dψ = real.(ifft(A, (1,2)))

    # orientational divergence (+ rotational diffusion)
    F̂θ = fft(Fθ, 3)
    ψ̂θ = dR > 0 ? fft(ψ, 3) : nothing
    B = similar(F̂θ)
    @inbounds for m in 1:G.Nθ, j in 1:G.Ny, i in 1:G.Nx
        n = G.kθ[m]
        nl = -im * n * F̂θ[i,j,m]
        if dealias && !G.keep_θ[m]
            nl = 0.0 + 0.0im
        end
        B[i,j,m] = dR > 0 ? nl - dR * n^2 * ψ̂θ[i,j,m] : nl
    end
    dψ .+= real.(ifft(B, 3))

    return dψ

end

function timestep(ψ, G::SpectralGrid; U=0.098175, λ=0.0, β=π/2, cfl=0.2, dt_max=Inf)

    u1, u2, E11, E12, E22 = velocity(ψ, G; β=β)

    ux = U + maximum(abs, u1)
    uy = U + maximum(abs, u2)
    # |θ̇| ≤ λ sqrt(((E22-E11)/2)² + E12²), maximized over θ
    θdot = λ == 0 ? 0.0 :
           abs(λ) * maximum(sqrt.(((E22 .- E11) ./ 2).^2 .+ E12.^2))

    rate = ux / G.dx + uy / G.dy + θdot / G.dθ
    dt = rate > 0 ? cfl / rate : dt_max
    return min(dt, dt_max), max(ux, uy) - U, θdot

end

function simulate(ψ0, G::SpectralGrid; tf=10.0,
                            U=0.098175, λ=0.0, β=π/2, dT=0.0, dR=0.0,
                            cfl=0.2, dt_max=Inf, ω_max=1.25, tplt=tf/20,
                            output_dir="", callback=nothing,
                            verbose=true, dealias=true)

    ψ = copy(ψ0)
    cell = G.dx * G.dy * G.dθ

    # explicit advection and implicit diffusion symbol D(k, n) = -(dT k² + dR n²)
    Nexp(f) = rhs(f, G; U=U, λ=λ, β=β, dT=0.0, dR=0.0, dealias=dealias)
    D = [-(dT * (G.kx[i]^2 + G.ky[j]^2) + dR * G.kθ[m]^2)
         for i in 1:G.Nx, j in 1:G.Ny, m in 1:G.Nθ]

    ψ_prev = similar(ψ)
    N_prev = similar(ψ)
    dt_prev = 0.0

    snapshots = NamedTuple[]

    function record!(t)
        ρ, m1, m2 = moments(ψ, G)
        u1, u2, _, _, _ = velocity(ψ, G; β=β)
        snap = (t=t, ρ=copy(ρ), m1=copy(m1), m2=copy(m2), u1=copy(u1), u2=copy(u2),
                mass=sum(ψ)*cell, minψ=minimum(ψ))
        push!(snapshots, snap)
        if !isempty(output_dir)
            mkpath(output_dir)
            path = joinpath(output_dir, "frame_$(lpad(length(snapshots)-1, 6, '0')).dat")
            open(path, "w") do io
                @printf(io, "# t = %.8f   Nx = %d   Ny = %d\n", t, G.Nx, G.Ny)
                println(io, "# x y rho m1 m2 u1 u2")
                for j in 1:G.Ny, i in 1:G.Nx
                    @printf(io, "%.8e %.8e %.8e %.8e %.8e %.8e %.8e\n",
                            G.x[i], G.y[j], ρ[i,j], m1[i,j], m2[i,j], u1[i,j], u2[i,j])
                end
            end
        end
        callback === nothing || callback(snap, G)
        return snap
    end

    t = 0.0
    next_save = tplt
    s0 = record!(t)
    mass0 = s0.mass
    verbose && @printf("t = %8.4f  mass = %.12e  min ψ = %+.3e\n", t, s0.mass, s0.minψ)

    nstep = 0
    while t < tf

        dt, umax, θdotmax = timestep(ψ, G; U=U, λ=λ, β=β,
                                               cfl=cfl, dt_max=dt_max)
        nstep > 0 && (dt = min(dt, ω_max * dt_prev))

        # land on the next save time without leaving a tiny final step, which
        # would make the following step ratio large
        t_stop = min(tf, next_save)
        if t + dt >= t_stop - 1e-12
            dt = t_stop - t
        elseif t + 2dt > t_stop
            dt = (t_stop - t) / 2
        end

        # SBDF2 (variable step); ω = 0 on the first step gives IMEX Euler
        ω  = nstep == 0 ? 0.0 : dt / dt_prev
        a0 = (1 + 2ω) / (1 + ω)
        a1 = -(1 + ω)
        a2 = ω^2 / (1 + ω)

        Nn  = Nexp(ψ)
        rhs = nstep == 0 ? ψ .+ dt .* Nn :
              -a1 .* ψ .- a2 .* ψ_prev .+ dt .* ((1 + ω) .* Nn .- ω .* N_prev)
        ψ̂ = fft(rhs) ./ (a0 .- dt .* D)

        ψ_prev .= ψ
        N_prev .= Nn
        dt_prev = dt
        ψ = real.(ifft(ψ̂))

        t += dt
        nstep += 1

        if t >= next_save - 1e-12
            s = record!(t)
            verbose && @printf("t = %8.4f  dt = %.2e  |u|max = %.3e  |θ̇|max = %.3e  Δmass/mass = %+.2e  min ψ = %+.3e\n",
                               t, dt, umax, θdotmax, (s.mass - mass0)/mass0, s.minψ)
            next_save += tplt
        end

    end

    verbose && @printf("done: %d steps\n", nstep)
    return ψ, snapshots

end

# -- Initial conditions --------------------------------------------------------

function ic_vonmises(G::SpectralGrid, ρ, θ0; ζ)

    ψ = zeros(G.Nx, G.Ny, G.Nθ)

    for j in 1:G.Ny, i in 1:G.Nx
        w = exp.(ζ .* cos.(G.θ .- θ0(G.x[i], G.y[j])))
        w ./= sum(w) * G.dθ #∫ w dθ = 1
        @views ψ[i,j,:] .= ρ(G.x[i], G.y[j]) .* w
    end

    return ψ

end

# Uniform von Mises state perturbed by plane waves in (x, y, θ):
#   ψ = ρ0 w(θ - θ0) [1 + Σ ε cos(kx x + ky y + nθ θ + φ)]
# nθ = 0 perturbs the density, nθ = ±1 the mean orientation, nθ = ±2 the spread
function ic_polar(G::SpectralGrid; ρ0=1.0, θ0=0.0, ζ=5.0, modes=())

    budget = sum(mode -> abs(mode.ε), modes; init=0.0)
    budget < 1 || error("perturbation too large: need Σ|ε| < 1 for ψ ≥ 0 (got $budget)")

    w = exp.(ζ .* cos.(G.θ .- θ0))
    w ./= sum(w) * G.dθ

    ψ = zeros(G.Nx, G.Ny, G.Nθ)
    for j in 1:G.Ny, i in 1:G.Nx
        δ = ones(G.Nθ)
        for mode in modes
            δ .+= mode.ε .* cos.(2π * mode.nx * G.x[i] / G.Lx .+ 2π * mode.ny * G.y[j] / G.Ly .+ mode.nθ .* G.θ .+ mode.phase)
        end
        @views ψ[i,j,:] .= ρ0 .* w .* δ
    end

    return ψ

end

# Random plane waves with spatial wavenumber |(nx, ny)| ∈ [nmin, nmax] and angular wavenumber |nθ| ≤ nθmax
function random_modes(nmodes::Int; nmin=1, nmax=4, nθmax=2, ε=1e-2, seed=0)

    rng = MersenneTwister(seed)

    # enumerate the band, keeping one of each ±(nx,ny,nθ) pair
    candidates = NTuple{3,Int}[]
    for nθ in -nθmax:nθmax, ny in -nmax:nmax, nx in -nmax:nmax
        (nx == 0 && ny == 0) && continue
        n = hypot(nx, ny)
        (nmin - 1e-9 <= n <= nmax + 1e-9) || continue
        (-nx, -ny, -nθ) in candidates && continue
        push!(candidates, (nx, ny, nθ))
    end

    nkeep = min(nmodes, length(candidates))
    nkeep < nmodes && @warn "band holds only $nkeep distinct waves; using all of them"

    picked = candidates[randperm(rng, length(candidates))[1:nkeep]]

    return [(nx = nx, ny = ny, nθ = nθ, ε = ε, phase = 2π * rand(rng)) for (nx, ny, nθ) in picked]

end

function ic_patch(G::SpectralGrid; ρ0=1.0, R=1.0, center=nothing, width=0.25, ζ=1.0)
    xc, yc = something(center, (G.Lx/2, G.Ly/2))
    ρfun(x, y) = ρ0 * 0.5 * (1 - tanh((hypot(x - xc, y - yc) - R) / width))
    θfun(x, y) = atan(y - yc, x - xc)
    return ic_vonmises(G, ρfun, θfun; ζ=ζ)
end

# Band of width W localized in x with centerline xc + δ(y), polarized along θ0
function ic_band(G::SpectralGrid; ρ0=1.0, W=1.0, xc=nothing, width=0.25, θ0=0.0, ζ=5.0, δ=y -> 0.0)
    xc = something(xc, G.Lx/2)
    ρfun(x, y) = ρ0 * 0.5 * (tanh((x - xc - δ(y) + W/2) / width) - tanh((x - xc - δ(y) - W/2) / width))
    return ic_vonmises(G, ρfun, (x, y) -> θ0; ζ=ζ)
end
